func auditStoredResult(store *storage.Store, id string) (bool, string) {
	stored, err := store.Load(id)
	if err != nil {
		return false, fmt.Sprintf("AUDIT_FAIL: %s (reason: load error: %v)\n", id, err)
	}

	warnEnvMismatch(stored)

	status, expected, computed, err := store.Verify(id)
	if err != nil {
		return false, fmt.Sprintf("AUDIT_FAIL: %s (reason: checksum verification error: %v)\n", id, err)
	}
	if status == storage.StatusNoChecksum {
		return false, fmt.Sprintf("AUDIT_FAIL: %s (reason: checksum missing)\n", id)
	}
	if status == storage.StatusCorrupted {
		return false, fmt.Sprintf("AUDIT_FAIL: %s (reason: checksum mismatch expected=%s computed=%s)\n", id, expected, computed)
	}

	seedStr, ok := stored.Metadata["seed"]
	if !ok {
		return false, fmt.Sprintf("AUDIT_FAIL: %s (reason: missing seed in metadata)\n", id)
	}
	seed, err := strconv.ParseInt(seedStr, 10, 64)
	if err != nil {
		return false, fmt.Sprintf("AUDIT_FAIL: %s (reason: invalid seed in metadata: %v)\n", id, err)
	}

	fn, err := engine.Get(stored.ExperimentName)
	if err != nil {
		return false, fmt.Sprintf("AUDIT_FAIL: %s (reason: experiment error: %v)\n", id, err)
	}

	rng := engine.NewRNG(seed)
	reexec, err := fn(stored.ExperimentName, stored.Parameters, rng)
	if err != nil {
		return false, fmt.Sprintf("AUDIT_FAIL: %s (reason: experiment error: %v)\n", id, err)
	}

	maxLen := len(stored.Values)
	if len(reexec.Values) > maxLen {
		maxLen = len(reexec.Values)
	}

	var mismatches []string
	for i := 0; i < maxLen; i++ {
		storedMissing := i >= len(stored.Values)
		reexecMissing := i >= len(reexec.Values)

		var storedVal, reexecVal string
		if storedMissing {
			storedVal = "<missing>"
		} else {
			storedVal = strconv.FormatFloat(stored.Values[i], 'g', -1, 64)
		}
		if reexecMissing {
			reexecVal = "<missing>"
		} else {
			reexecVal = strconv.FormatFloat(reexec.Values[i], 'g', -1, 64)
		}

		if storedMissing || reexecMissing || math.Float64bits(stored.Values[i]) != math.Float64bits(reexec.Values[i]) {
			mismatches = append(mismatches, fmt.Sprintf("  value[%d]: stored=%s, re-executed=%s", i, storedVal, reexecVal))
		}
	}

	if len(mismatches) == 0 {
		return true, fmt.Sprintf("AUDIT_PASS: %s\n", id)
	}

	var sb strings.Builder
	sb.WriteString(fmt.Sprintf("AUDIT_FAIL: %s\n", id))
	for _, m := range mismatches {
		sb.WriteString(m)
		sb.WriteByte('\n')
	}
	return false, sb.String()
}

func warnEnvMismatch(stored *storage.StoredResult) {
	msg, ok := envMismatchWarning(stored.Metadata)
	if ok {
		fmt.Fprintln(os.Stderr, msg)
	}
}

func envMismatchWarning(metadata map[string]string) (string, bool) {
	current := environmentMetadata()
	fields := []string{"env_go_version", "env_os", "env_arch", "env_hostname"}

	var diffs []string
	for _, field := range fields {
		if metadata[field] != current[field] {
			diffs = append(diffs, fmt.Sprintf("%s stored=%q current=%q", field, metadata[field], current[field]))
		}
	}

	if len(diffs) == 0 {
		return "", false
	}
	return fmt.Sprintf("WARNING: ENV_MISMATCH (%s)", strings.Join(diffs, ", ")), true
}
